const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const hikes = [
  { id: 'h1', name: 'Ridge Loop', date: '2026-10-04', distanceKm: 8.4 },
  { id: 'h2', name: 'Old Mill Creek', date: '2026-09-12', distanceKm: 5.1 },
  { id: 'h3', name: 'Lake Trail', date: '2026-10-19', distanceKm: 11.2 },
  { id: 'h4', name: 'Eagle Point', date: '2025-10-02', distanceKm: 14.0 },
  { id: 'h5', name: 'Fern Gully', date: '2026-09-28', distanceKm: 3.6 },
];

function groupHikesByMonth(hikes) {
  const sorted = [...hikes].sort((a, b) => b.date.localeCompare(a.date));
  const sections = [];
  for (const hike of sorted) {
    const year = hike.date.slice(0, 4);
    const month = MONTHS[Number(hike.date.slice(5, 7)) - 1];
    const title = `${month} ${year}`;
    const last = sections[sections.length - 1];
    if (last && last.title === title) last.data.push(hike);
    else sections.push({ title, data: [hike] });
  }
  return sections;
}

console.log(JSON.stringify(groupHikesByMonth(hikes), null, 2));
